type Monster = {
  name: string
  floors: string
  hp: number
  atk: number
  def?: number
  exp?: number
  special?: string
  notes?: string
  drop?: string
}

type ItemCategory = { label?: string; category?: string; items: string[] }

type HeartInfo = {
  monsterName: string
  heartName?: string
  recruitRate?: number
  clawChance?: string
}

type ModContent = {
  additionalItems?: string[]
  additionalMonsters?: Monster[]
  hearts?: HeartInfo[]
}

type DungeonData = {
  name: string
  description: string
  monsters: Monster[]
  itemCategories: ItemCategory[]
  traps?: string[]
  statues?: string[]
  treasureRooms?: { floor: number; description: string }[]
  strategy: string
  modContent?: ModContent
}

